await fetch('/?rig_ttfb_client=1',{method:'POST',body:JSON.stringify({label:"events-anon",host:location.host,loggedIn:document.body.classList.contains('logged-in'),nav:performance.getEntriesByType('navigation').map((n)=>({ttfb:Math.round(n.responseStart-n.requestStart),dcl:Math.round(n.domContentLoadedEventEnd),load:Math.round(n.loadEventEnd)})),resources:performance.getEntriesByType('resource').length,out})});return out.length})()"}]

